def choose_move(observation):
    wx, hy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    score_self, score_opp = observation['scores']
    path_self = observation['self_path']
    path_opp = observation['opponent_path']
    # Determine closest resource
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    res = min(resources, key=lambda r: dist((px,py), r), default=None)
    # Move towards resource if exists
    if res:
        dx = dy = 0
        if res[0] > px: dx=1
        elif res[0] < px: dx=-1
        if res[1] > py: dy=1
        elif res[1] < py: dy=-1
        # Prioritize horizontal movement
        if dx != 0:
            candidate = (px + dx, py)
            if 0 <= candidate[0] < wx and 0 <= candidate[1] < hy and candidate not in obstacles:
                return [dx, 0]
        if dy != 0:
            candidate = (px, py + dy)
            if 0 <= candidate[0] < wx and 0 <= candidate[1] < hy and candidate not in obstacles:
                return [0, dy]
    # Otherwise, move to maximize distance from opponent
    dx=dy=0
    if ox > px:
        dx=-1
    elif ox < px:
        dx=1
    if oy > py:
        dy=-1
    elif oy < py:
        dy=1
    # Avoid obstacles
    candidates = []
    for delta in [[dx,0],[0,dy], [dx,dy], [0,0]]:
        nx, ny = px+delta[0], py+delta[1]
        if 0<=nx<wx and 0<=ny<hy and (nx,ny) not in obstacles:
            candidates.append((delta[0], delta[1]))
    # Pick candidate that moves away from opponent
    def score_move(delta):
        nx, ny = px+delta[0], py+delta[1]
        return dist((nx, ny), (ox, oy))
    best = max(candidates, key=score_move) if candidates else [0,0]
    return list(best)
